import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Mesh, PlaneGeometry, Group } = ctx.THREE;

  const group = new Group();
  group.position.set(0, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Geometry: 512px / 320px ≈ 1.6:1 aspect
  const aspect = 512 / 320;
  const height = 2.0;
  const width = height * aspect;
  const geometry = new PlaneGeometry(width, height, 1, 1);

  // Load the image asynchronously
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/orb-decor.png';
  let imageTex = null;
  let material = null;
  let mesh = null;

  const initMaterial = (tex) => {
    imageTex = tex;
    if (imageTex) {
      imageTex.colorSpace = 'srgb';
    }

    // TSL material with engineered grain overlay
    const uvNode = uv();

    // Grain pattern (subtle procedural noise simulation via sin/cos modulation)
    const grainAmount = 0.03;
    const grain = mix(
      vec3(1.0),
      vec3(
        Math.sin(uvNode.x * 50.0 + uvNode.y * 30.0) * 0.5 + 0.5,
        Math.cos(uvNode.x * 40.0 + uvNode.y * 40.0) * 0.5 + 0.5,
        Math.sin((uvNode.x + uvNode.y) * 35.0) * 0.5 + 0.5
      ),
      grainAmount
    );

    let colorNode = imageTex ? texture(imageTex, uvNode) : vec3(0.1, 0.1, 0.1);
    colorNode = mix(colorNode, grain, grainAmount);

    material = new MeshBasicNodeMaterial({
      colorNode,
      transparent: true,
      side: 2, // DoubleSide
    });

    mesh = new Mesh(geometry, material);
    group.clear();
    group.add(mesh);
  };

  // Fallback material while loading
  const fallbackMaterial = new MeshBasicNodeMaterial({
    color: 0x0b0b10,
    transparent: true,
    side: 2,
  });
  const fallbackMesh = new Mesh(geometry, fallbackMaterial);
  group.add(fallbackMesh);

  // Async load
  ctx.textureLoader
    .loadTexture(imageUrl)
    .then((tex) => {
      initMaterial(tex);
    })
    .catch((err) => {
      console.warn('Failed to load image texture:', err);
      // Keep fallback material
    });

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    fallbackMaterial.dispose();
    if (material) {
      material.dispose();
    }
    if (imageTex) {
      imageTex.dispose();
    }
  };

  group.userData.handlers = {};

  return group;
}
